import { useRef, useState, type FormEvent } from "react"
import {
  ArrowUp,
  ArrowUpRight,
  Box,
  Check,
  ChevronDown,
  CircleDashed,
  Code2,
  Feather,
  FileText,
  Globe2,
  GraduationCap,
  Hexagon,
  Lightbulb,
  Menu,
  MoreHorizontal,
  Orbit,
  Paperclip,
  Sparkles,
  X,
  Zap,
} from "lucide-react"
import { ArcFlowBackground } from "./ArcFlowBackground"
import { sphereOrbImage } from "./orb-asset"
import "./hero-sphere-ai.css"

type PromptMode = "Brainstorm" | "Code" | "Text" | "Advice" | "More"

const promptModes = [
  { label: "Brainstorm" as const, icon: Lightbulb, placeholder: "What would you like to brainstorm?" },
  { label: "Code" as const, icon: Code2, placeholder: "Describe what you want to build..." },
  { label: "Text" as const, icon: FileText, placeholder: "What would you like to write?" },
  { label: "Advice" as const, icon: GraduationCap, placeholder: "What do you need advice on?" },
  { label: "More" as const, icon: MoreHorizontal, placeholder: "Ask Anything" },
]

const brandLogos = [
  { name: "Boltshift", icon: Zap },
  { name: "Lightbox", icon: Box },
  { name: "FeatherDev", icon: Feather },
  { name: "Spherule", icon: Orbit },
  { name: "GlobalBank", icon: Hexagon },
]

export type HeroSphereAIProps = {
  className?: string
  brandName?: string
  renderBackground?: boolean
  content?: {
    badge: string
    title: string
    description: string
    buttonText: string
    placeholder: string
    suggestions: string
  }
  onPromptSubmit?: (prompt: string, mode: PromptMode, file: File | null) => void
}

export function HeroSphereAI({
  className = "",
  brandName = "CreghtAI",
  renderBackground = true,
  content,
  onPromptSubmit,
}: HeroSphereAIProps) {
  const [prompt, setPrompt] = useState("")
  const [mode, setMode] = useState<PromptMode | null>(null)
  const [file, setFile] = useState<File | null>(null)
  const [status, setStatus] = useState("")
  const [locale, setLocale] = useState<"en" | "zh">("en")
  const [openMenu, setOpenMenu] = useState<"navigation" | "resources" | "pricing" | "language" | null>(null)
  const promptRef = useRef<HTMLTextAreaElement>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  const focusPrompt = () => {
    setOpenMenu(null)
    promptRef.current?.focus()
    promptRef.current?.scrollIntoView({ behavior: "smooth", block: "center" })
  }

  const submitPrompt = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const value = prompt.trim()
    if (!value) {
      focusPrompt()
      return
    }
    onPromptSubmit?.(value, mode ?? "More", file)
    setStatus(
      onPromptSubmit
        ? "Your request has been sent."
        : "Prompt captured. Connect an AI service to generate a response.",
    )
  }

  const activeMode = promptModes.find((item) => item.label === mode)
  const placeholder = locale === "zh" ? "输入你的想法..." : activeMode?.placeholder ?? content?.placeholder ?? "Ask Anything"
  const titleLines = (content?.title ?? "Build {orb} create\nwith generative AI.").split("\n")
  const [beforeOrb, afterOrb = ""] = (titleLines[0] ?? "").split("{orb}")
  const modeLabels = content?.suggestions.split("\n").map((label) => label.trim()).filter(Boolean) ?? []

  return (
    <section className={`sphere-ai-hero ${className}`} id="sphere-ai-top">
      {renderBackground && <ArcFlowBackground />}

      <header className="sphere-ai-header">
        <a className="sphere-ai-logo" href="#sphere-ai-top" aria-label={`${brandName} home`}>
          <CircleDashed aria-hidden="true" size={26} strokeWidth={1.6} />
          <span>{brandName}</span>
        </a>

        <nav className={`sphere-ai-nav ${openMenu === "navigation" ? "is-open" : ""}`} aria-label="Main navigation">
          <a href="#sphere-ai-top" onClick={() => setOpenMenu(null)}>Home</a>
          <a href="#sphere-ai-capabilities" onClick={() => setOpenMenu(null)}>Features</a>
          <button type="button" onClick={() => setOpenMenu(openMenu === "pricing" ? null : "pricing")}>Pricing</button>
          <button
            type="button"
            aria-expanded={openMenu === "resources"}
            onClick={() => setOpenMenu(openMenu === "resources" ? null : "resources")}
          >
            Resources <ChevronDown size={15} strokeWidth={1.6} aria-hidden="true" />
          </button>
          {openMenu === "resources" && (
            <div className="sphere-ai-nav-popover" role="menu">
              <button type="button" role="menuitem" onClick={() => { setPrompt("Help me brainstorm a new product idea for..."); focusPrompt() }}>
                Prompt starter
              </button>
              <button type="button" role="menuitem" onClick={() => { setMode("Code"); focusPrompt() }}>
                Explore coding
              </button>
            </div>
          )}
          {openMenu === "pricing" && (
            <div className="sphere-ai-nav-popover sphere-ai-pricing-popover" role="status">
              <strong>Explore {brandName}</strong>
              <span>Start with an idea and discover what you can create.</span>
              <button type="button" onClick={focusPrompt}>Try the prompt <ArrowUpRight size={14} /></button>
            </div>
          )}
        </nav>

        <div className="sphere-ai-header-actions">
          <button className="sphere-ai-get-started" type="button" onClick={focusPrompt}>
            <span>{content?.buttonText ?? "Get Started"}</span>
            <span className="sphere-ai-get-started-icon"><ArrowUpRight size={16} strokeWidth={1.5} /></span>
          </button>
          <button
            className="sphere-ai-mobile-menu"
            type="button"
            aria-label={openMenu === "navigation" ? "Close menu" : "Open menu"}
            aria-expanded={openMenu === "navigation"}
            onClick={() => setOpenMenu(openMenu === "navigation" ? null : "navigation")}
          >
            {openMenu === "navigation" ? <X size={21} /> : <Menu size={21} />}
          </button>
        </div>
      </header>

      <main className="sphere-ai-main">
        <div className="sphere-ai-eyebrow">
          <Sparkles size={17} fill="currentColor" strokeWidth={1.3} aria-hidden="true" />
          {content?.badge ?? "Experience the power of our generative AI engine"}
        </div>

        <h1 className="sphere-ai-title">
          <span className="sphere-ai-title-first">
            <span>{beforeOrb.trim()}</span>
            {titleLines[0]?.includes("{orb}") && <img src={sphereOrbImage} alt="" aria-hidden="true" />}
            <span>{afterOrb.trim()}</span>
          </span>
          <span className="sphere-ai-title-second">{titleLines.slice(1).join(" ")}</span>
        </h1>

        <div className="sphere-ai-modes" id="sphere-ai-capabilities" aria-label="Prompt categories">
          {promptModes.map(({ label, icon: Icon }, index) => (
            <button
              key={label}
              className={mode === label ? "is-selected" : ""}
              type="button"
              aria-pressed={mode === label}
              onClick={() => { setMode(label); setStatus(""); focusPrompt() }}
            >
              {label !== "More" && <Icon size={17} strokeWidth={1.55} aria-hidden="true" />}
              {modeLabels[index] ?? label}
            </button>
          ))}
        </div>

        <form className="sphere-ai-prompt" id="sphere-ai-prompt" onSubmit={submitPrompt}>
          <label className="sphere-ai-sr-only" htmlFor="sphere-ai-input">Ask {brandName} anything</label>
          <textarea
            ref={promptRef}
            id="sphere-ai-input"
            value={prompt}
            onChange={(event) => { setPrompt(event.target.value); setStatus("") }}
            placeholder={placeholder}
            rows={2}
            maxLength={2000}
          />
          <div className="sphere-ai-prompt-toolbar">
            <div className="sphere-ai-prompt-tools">
              <input
                ref={fileRef}
                className="sphere-ai-sr-only"
                type="file"
                accept="image/*,.pdf,.txt"
                tabIndex={-1}
                onChange={(event) => { setFile(event.target.files?.[0] ?? null); setStatus("") }}
              />
              <button type="button" aria-label="Attach a file" title="Attach a file" onClick={() => fileRef.current?.click()}>
                {file ? <Check size={17} /> : <Paperclip size={17} />}
              </button>
              <div className="sphere-ai-language-wrap">
                <button
                  type="button"
                  aria-label="Choose language"
                  title="Choose language"
                  aria-expanded={openMenu === "language"}
                  onClick={() => setOpenMenu(openMenu === "language" ? null : "language")}
                >
                  <Globe2 size={17} />
                </button>
                {openMenu === "language" && (
                  <div className="sphere-ai-language-menu" role="menu">
                    <button type="button" role="menuitemradio" aria-checked={locale === "en"} onClick={() => { setLocale("en"); setOpenMenu(null) }}>English</button>
                    <button type="button" role="menuitemradio" aria-checked={locale === "zh"} onClick={() => { setLocale("zh"); setOpenMenu(null) }}>中文</button>
                  </div>
                )}
              </div>
              {file && <span className="sphere-ai-file-name" title={file.name}>{file.name}</span>}
            </div>
            <button className="sphere-ai-send" type="submit" aria-label="Submit prompt" title="Submit prompt">
              <ArrowUp size={18} strokeWidth={1.5} />
            </button>
          </div>
        </form>
        <p className="sphere-ai-status" role="status">{status}</p>

        <div className="sphere-ai-trust" id="sphere-ai-trust">
          <p>{content?.description ?? "Join 4,000+ companies already growing"}</p>
          <div className="sphere-ai-logos" aria-label="Trusted companies">
            {brandLogos.map(({ name, icon: Icon }, index) => (
              <div className="sphere-ai-brand" key={name}>
                {index > 0 && <span className="sphere-ai-brand-divider" aria-hidden="true" />}
                <Icon size={index === 2 ? 26 : 25} strokeWidth={index === 2 ? 2.5 : 2.1} aria-hidden="true" />
                <strong>{name}</strong>
              </div>
            ))}
          </div>
        </div>
      </main>
    </section>
  )
}

export default HeroSphereAI

// Sphere Blue shader exported from Gradient Atlas Arc Flow.
// https://p9lj5699n5ua.preview.creght.cn/?dev
export const vertexShader = "#version 300 es
    void main() {
      vec2 p = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
      gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
    }
"

export const fragmentShader = "#version 300 es
    precision highp float;
    out vec4 fragColor;
    uniform vec2 u_resolution;
    uniform int u_mode;
    uniform float u_time, u_curve, u_offset, u_width, u_flow, u_light, u_grain, u_seed;
    uniform vec3 u_top, u_mid, u_warm, u_mint, u_blue, u_cyan;

    float hash21(vec2 p) {
      p = fract(p * vec2(123.34, 345.45));
      p += dot(p, p + 34.345);
      return fract(p.x * p.y);
    }
    float noise21(vec2 p) {
      vec2 i = floor(p), f = fract(p);
      f = f * f * (3.0 - 2.0 * f);
      return mix(mix(hash21(i), hash21(i + vec2(1,0)), f.x),
                 mix(hash21(i + vec2(0,1)), hash21(i + vec2(1,1)), f.x), f.y);
    }
    float fbm(vec2 p) {
      float a = 0.0, s = 0.5;
      for (int i=0; i<4; i++) { a += noise21(p) * s; p = p * 2.03 + 17.7; s *= 0.5; }
      return a;
    }
    float gauss(float x, float spread) { return exp(-x*x / (spread*spread)); }

    vec3 meshMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0, 781.0);
      vec2 q = uv + vec2(u_offset / 1550.0, u_curve / 1700.0);
      vec2 warp = vec2(fbm(q*2.5+vec2(tm*.09,seed)), fbm(q*2.8+vec2(seed,-tm*.08))) - .48;
      q += warp * .17 * u_flow;
      float w = max(.45, u_width);
      float a = gauss(length((q-vec2(.08+.05*sin(tm*.28),.72))*vec2(1.05,1.0)),.37*w);
      float b = gauss(length((q-vec2(.82,.22+.07*cos(tm*.21)))*vec2(1.0,1.18)),.37*w);
      float c = gauss(length((q-vec2(.64+.05*sin(tm*.18+seed),.77))*vec2(1.0,1.2)),.32*w);
      float d = gauss(length((q-vec2(.28,.20))*vec2(1.2,1.0)),.28*w);
      vec3 color = mix(u_top,u_mid,smoothstep(.05,1.05,uv.y));
      color = mix(color,u_warm,clamp(a*.72*u_light,0.0,.95));
      color = mix(color,u_mint,b*.78);
      color = mix(color,u_blue,c*.63);
      color = mix(color,u_cyan,d*.45);
      return color;
    }

    vec3 satinMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0,781.0);
      vec2 q = (uv-vec2(.50+u_offset/2200.0,.52+u_curve/2200.0))*vec2(1.42,1.0);
      float r = length(q)+.001;
      float a = atan(q.y,q.x);
      float twist = a*1.7 + r*8.6/max(.55,u_width)
                  + 1.04*sin(a*2.0-r*6.0+tm*.25+seed*.14)*u_flow + tm*.20;
      float fold = sin(twist+1.08*sin(r*7.2-a*1.4+tm*.11));
      float broad = smoothstep(-.75,.80,fold);
      vec3 color = mix(u_top,u_blue,broad*.83);
      color = mix(color,u_mid,gauss(fold+.22,.34)*.39);
      float specular = gauss(fold-.72,.14) + gauss(fold+.62,.11)*.35;
      color = mix(color,u_warm,clamp(specular*.66*u_light,0.0,.88));
      color = mix(color,u_mint,gauss(fold-.27,.11)*.30);
      color *= 1.0-.20*smoothstep(.48,.9,r);
      return color;
    }

    vec3 eclipseMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0,781.0);
      vec2 q = (uv-vec2(.52+u_offset/2600.0,.52+u_curve/2600.0))*vec2(1.42,1.0);
      float theta = atan(q.y,q.x);
      float r = length(q);
      float radius = .35+.006*u_flow*sin(theta*5.0+tm*.24+seed);
      vec3 color = mix(u_top,u_blue,smoothstep(0.0,1.0,uv.y)*.5)*.36;
      color += u_mid*gauss(r-radius,.22*u_width)*.12;
      float disk = 1.0-smoothstep(radius-.022,radius+.007,r);
      color = mix(color,vec3(.003,.005,.020),disk*.98);
      float arc = .44+.56*smoothstep(-.8,.8,sin(theta-.55));
      float halo = gauss(r-radius,.071*u_width);
      float rim = gauss(r-radius,.013*u_width);
      color += u_cyan*halo*.52*arc*u_light;
      color += mix(u_mint,u_warm,.5+.5*sin(theta+tm*.12))*rim*1.30*arc*u_light;
      color += u_warm*gauss(r-radius-.014,.035*u_width)*.15*u_light;
      return color;
    }

    vec3 curtainMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0,781.0);
      vec2 q = uv;
      q.x += u_offset/2200.0 + .028*u_flow*sin(q.y*6.0+tm*.27);
      q.x += (fbm(vec2(q.x*5.0,q.y*2.0+tm*.05)+seed)-.5)*.045*u_flow;
      vec3 color = mix(u_top,u_blue,smoothstep(0.0,1.0,q.y)*.56);
      color = mix(color,u_mid,.24+.12*sin(q.y*3.4+tm*.12));
      float glow = gauss(q.y-.75,.53)*u_light;
      for(int i=0;i<7;i++) {
        float fi = float(i);
        float center = (fi+.5)/7.0+.018*sin(q.y*5.0+tm*.31+fi*1.6)*u_flow;
        float spread = (.020+.013*fract(fi*.57)) * u_width;
        float ray = gauss(q.x-center,spread);
        vec3 tint = mix(u_cyan,u_warm,fract(fi*.618));
        color += tint*ray*(.13+.19*glow);
      }
      float broad = .5+.5*sin(q.x*(14.0+u_curve*.025)+sin(q.y*7.0+tm*.22)*u_flow);
      color = mix(color,u_mint,pow(broad,5.0)*.16*glow);
      color += u_warm*gauss(q.y-1.02,.35)*.12*u_light;
      return color;
    }

    vec3 cloudMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0,781.0);
      vec2 q = (uv-vec2(.50+u_offset/2200.0,.52+u_curve/2200.0))*vec2(1.42,1.0);
      float a = atan(q.y,q.x);
      float n = fbm(q*4.8/max(.6,u_width)+vec2(tm*.08+seed,-tm*.06));
      float r = length(q)+(.5-n)*.19*u_flow+.024*sin(a*5.0+tm*.27);
      vec3 color = mix(u_top,u_mid,smoothstep(.06,.78,r));
      float cloud = 1.0-smoothstep(.19,.55,r);
      color = mix(color,u_blue,cloud*.90);
      color = mix(color,u_cyan,gauss(r-.40,.17*u_width)*.45);
      color = mix(color,u_mint,gauss(r-.66,.23*u_width)*.22);
      color += u_warm*gauss(r-.64,.31)*.14*u_light;
      return color;
    }

    vec3 moonMode(vec2 p, float tm, float seed) {
      vec2 uv = p / vec2(1107.0,781.0);
      float x = (uv.x-.5)*2.0;
      float curve = .225 + u_curve/1400.0;
      float arc = .405 + u_offset/1450.0 + curve*x*x;
      float n = fbm(vec2(x*2.5+seed,tm*.065));
      arc += (n-.48)*.012*u_flow + .004*u_flow*sin(x*4.0+tm*.28+seed);
      float d = uv.y-arc;

      vec3 upper = mix(u_top,u_mid,smoothstep(.0,.9,uv.y)*.12);
      vec3 body = mix(u_blue,u_warm*.16,smoothstep(.06,.62,d)*.18);
      vec3 color = mix(upper,body,smoothstep(-.038,.075,d));

      float atmosphere = gauss(d+.038,.143*u_width);
      float outer = gauss(d+.067,.055*u_width);
      float rim = gauss(d+.016,.022*u_width);
      float inner = gauss(d-.048,.062*u_width);
      vec3 coolRim = mix(u_mint,u_cyan,smoothstep(-.82,.78,x)*.37);
      float shimmer = .93+.07*sin(x*3.4-tm*.21+seed);
      color += u_cyan*atmosphere*.22*u_light;
      color += coolRim*outer*.55*u_light*shimmer;
      color += u_mint*rim*.67*u_light;
      color += u_warm*inner*.26*u_light;

      float lowerGlow = gauss(d-.12,.16*u_width)*.09*u_light;
      color += u_warm*lowerGlow;
      color *= 1.0-.10*smoothstep(.35,.72,uv.y);
      return color;
    }

    void main() {
      // A fixed design coordinate system keeps the same composition at any export size.
      float scale = max(u_resolution.x / 1107.0, u_resolution.y / 781.0);
      vec2 p = (gl_FragCoord.xy - 0.5 * u_resolution) / scale + vec2(553.5, 390.5);
      p.y = 781.0 - p.y;
      float x = p.x, y = p.y;
      float tm = u_time;
      float seed = u_seed * 1.137;

      if (u_mode != 0) {
        vec3 variant;
        if (u_mode == 1) variant = meshMode(p,tm,seed);
        else if (u_mode == 2) variant = satinMode(p,tm,seed);
        else if (u_mode == 3) variant = eclipseMode(p,tm,seed);
        else if (u_mode == 4) variant = curtainMode(p,tm,seed);
        else if (u_mode == 5) variant = cloudMode(p,tm,seed);
        else variant = moonMode(p,tm,seed);
        float grain = (hash21(gl_FragCoord.xy+floor(tm*16.0))-.5)*u_grain;
        fragColor = vec4(clamp(variant+grain,0.0,1.0),1.0);
        return;
      }

      vec3 sky = mix(u_top, u_mid, smoothstep(45.0, 435.0, y));
      sky = mix(sky, u_warm, smoothstep(342.0, 635.0, y) * 0.38);
      float sun = gauss((x-128.0) / 460.0, 1.0) * gauss((y-575.0) / 210.0, 1.0);
      sky = mix(sky, u_warm, clamp(sun * 0.79 * u_light, 0.0, 0.98));
      float lowerLeft = smoothstep(560.0, 750.0, y) * (1.0-smoothstep(130.0, 510.0, x));
      sky = mix(sky, u_cyan, lowerLeft * 0.58);

      // The large diagonal arc stays recognizable while its surface moves.
      float motion = u_flow;
      float phase = tm * 1.35;
      float dx = x - 192.0;
      float arc = 781.0 - 1.130 * dx + 0.000505 * dx * dx;
      float arcT = clamp(dx / 915.0, 0.0, 1.0);
      arc += u_curve * sin(3.14159265 * arcT) + u_offset;
      arc += motion * (9.0 * sin(x * 0.010 - phase + seed)
            + 4.0 * sin(x * 0.019 + phase * 0.68));
      float d = y - arc;
      float inside = smoothstep(-2.0, 3.0, d);

      vec2 np = vec2(x * 0.0058 - phase * 0.16, y * 0.009 + phase * 0.12) + seed;
      float n = fbm(np);
      float current = sin(x * 0.009 - phase + seed)
                    + 0.46 * sin(x * 0.018 + phase * 0.72 + seed * 0.3);
      float carried = d - motion * (22.0 * current + 35.0 * (n - 0.47));
      float bandA = gauss(carried - (168.0 + motion * 53.0 * sin(x * 0.007 - phase * 1.08 + seed)), 73.0*u_width);
      float bandB = gauss(carried - (339.0 + motion * 63.0 * sin(x * 0.008 + phase * 0.84 + seed * 0.4)), 96.0*u_width);
      float bandC = gauss(carried - (69.0 + motion * 30.0 * sin(x * 0.013 - phase * 1.22)), 32.0*u_width);
      float ribbonA = gauss(carried - (120.0 + motion * 42.0 * sin(x * 0.011 - phase * 1.35 + seed)), 21.0*u_width);
      float ribbonB = gauss(carried - (277.0 + motion * 54.0 * sin(x * 0.009 + phase * 1.13)), 30.0*u_width);

      vec3 wave = mix(u_mint, u_cyan, smoothstep(25.0, 210.0, d) * 0.52);
      wave = mix(wave, u_blue, smoothstep(112.0, 415.0, d) * 0.77);
      wave = mix(wave, u_blue, bandA * 0.82);
      wave = mix(wave, u_cyan, bandB * 0.56);
      wave = mix(wave, u_mint, bandC * 0.32);
      wave = mix(wave, u_cyan, ribbonA * 0.45 * min(motion, 1.5));
      wave = mix(wave, u_blue, ribbonB * 0.52 * min(motion, 1.5));
      wave += (n - 0.47) * 0.11 * motion;

      // Let the sky show through the upper part of the curved glass.
      float transmission = (1.0 - smoothstep(20.0, 310.0, d)) * 0.27;
      wave = mix(wave, mix(sky, u_cyan, 0.20), transmission);
      float glassDepth = gauss(d - 17.0, 18.0 * u_width);
      wave *= 1.0 - glassDepth * 0.19;
      wave = mix(wave, u_mint, gauss(d - 51.0, 45.0 * u_width) * 0.16);

      // Narrow travelling caustics and a soft specular sweep give the body polish.
      float causticA = gauss(carried - (152.0 + motion * 45.0 * sin(x * 0.012 - phase * 1.28 + seed)), 14.0 * u_width);
      float causticB = gauss(carried - (307.0 + motion * 53.0 * sin(x * 0.008 + phase * 0.96)), 20.0 * u_width);
      float sheen = gauss(carried - (208.0 + motion * 66.0 * sin(x * 0.006 - phase * 0.82)), 83.0 * u_width);
      wave += mix(u_cyan, vec3(0.94, 0.99, 1.0), 0.58) * (causticA * 0.18 + causticB * 0.12) * u_light;
      wave += vec3(0.35, 0.52, 0.61) * sheen * 0.13 * u_light;
      vec3 color = mix(sky, wave, inside);

      // A second ribbon crosses the bottom at a different rhythm.
      float lowerEdge = 707.0 - 172.0*smoothstep(515.0, 1110.0, x)
                      - 68.0*(1.0-smoothstep(0.0, 300.0, x))
                      + motion*31.0*sin(x*0.008 + phase*0.91 + seed);
      float lowerMask = smoothstep(-75.0, 80.0, y-lowerEdge);
      vec3 lower = mix(u_blue, u_cyan, smoothstep(300.0, 1100.0, x)*0.59);
      lower = mix(lower, u_blue, gauss(y-lowerEdge-38.0-motion*36.0*sin(x*0.008-phase), 70.0*u_width)*0.42);
      color = mix(color, lower, lowerMask * 0.81);

      // Paired bright and dark rims suggest a thick, refracting glass edge.
      float glint = 0.76 + 0.24 * sin(x * 0.021 - phase * 1.6);
      float outerHalo = gauss(d + 5.0, 17.0 * u_width) * 0.21 * u_light;
      float brightRim = gauss(d + 1.0, 3.1) * 0.78 * glint;
      float innerRim = gauss(d - 12.0, 4.5 * u_width) * 0.27 * glint;
      color = mix(color, u_cyan, outerHalo);
      color = mix(color, vec3(0.95, 0.99, 1.0), brightRim + innerRim);
      float grain = (hash21(gl_FragCoord.xy + floor(tm*16.0)) - 0.5) * u_grain;
      color = clamp(color + grain, 0.0, 1.0);
      fragColor = vec4(color, 1.0);
    }
"

import { useEffect, useRef } from "react"
import { fragmentShader, vertexShader } from "./arc-flow-shaders"

export const ARC_FLOW_DEFAULTS = {
  top: "#2e6fae",
  mid: "#b2cbd8",
  warm: "#fff1bc",
  mint: "#a6dcd3",
  blue: "#1747b7",
  cyan: "#68b0d5",
  curve: -22,
  offset: -21,
  width: 1,
  flow: 1.45,
  light: 1,
  grain: 0.009,
  seed: 3.1,
  speed: 1.3,
}
export type ArcFlowSettings = typeof ARC_FLOW_DEFAULTS

function rgb(hex: string) {
  return [1, 3, 5].map((index) => Number.parseInt(hex.slice(index, index + 2), 16) / 255)
}

function compileShader(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type)
  if (!shader) return null
  gl.shaderSource(shader, source)
  gl.compileShader(shader)
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader
  console.error("Arc Flow shader:", gl.getShaderInfoLog(shader))
  gl.deleteShader(shader)
  return null
}

export function ArcFlowBackground({
  className = "",
  ...settings
}: Partial<ArcFlowSettings> & { className?: string } = {}) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const settingsRef = useRef<ArcFlowSettings>({ ...ARC_FLOW_DEFAULTS, ...settings })
  settingsRef.current = { ...ARC_FLOW_DEFAULTS, ...settings }

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const gl = canvas.getContext("webgl2", { alpha: false, antialias: false })
    if (!gl) return

    const vertex = compileShader(gl, gl.VERTEX_SHADER, vertexShader)
    const fragment = compileShader(gl, gl.FRAGMENT_SHADER, fragmentShader)
    if (!vertex || !fragment) {
      if (vertex) gl.deleteShader(vertex)
      if (fragment) gl.deleteShader(fragment)
      return
    }

    const program = gl.createProgram()
    const vao = gl.createVertexArray()
    if (!program || !vao) return
    gl.attachShader(program, vertex)
    gl.attachShader(program, fragment)
    gl.linkProgram(program)
    gl.deleteShader(vertex)
    gl.deleteShader(fragment)
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      console.error("Arc Flow program:", gl.getProgramInfoLog(program))
      gl.deleteProgram(program)
      gl.deleteVertexArray(vao)
      return
    }

    gl.useProgram(program)
    gl.bindVertexArray(vao)
    const uniform = (name: string) => gl.getUniformLocation(program, `u_${name}`)
    const resolution = uniform("resolution")
    const time = uniform("time")
    gl.uniform1i(uniform("mode"), 0)
    const controls = ["curve", "offset", "width", "flow", "light", "grain", "seed"] as const
    const colors = ["top", "mid", "warm", "mint", "blue", "cyan"] as const
    const controlLocations = Object.fromEntries(controls.map((name) => [name, uniform(name)]))
    const colorLocations = Object.fromEntries(colors.map((name) => [name, uniform(name)]))

    let elapsed = 0
    let previousFrame = 0
    let frameId = 0
    let running = false
    let intersecting = true
    const motion = window.matchMedia("(prefers-reduced-motion: reduce)")

    const render = (now: number) => {
      const current = settingsRef.current
      const bounds = canvas.getBoundingClientRect()
      const ratio = Math.min(window.devicePixelRatio || 1, 1.6)
      const width = Math.max(2, Math.round(bounds.width * ratio))
      const height = Math.max(2, Math.round(bounds.height * ratio))
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width
        canvas.height = height
      }
      gl.viewport(0, 0, width, height)
      if (previousFrame && !motion.matches) elapsed += Math.min((now - previousFrame) / 1000, 0.1) * current.speed
      previousFrame = now
      controls.forEach((name) => gl.uniform1f(controlLocations[name], current[name]))
      colors.forEach((name) => gl.uniform3fv(colorLocations[name], rgb(current[name])))
      gl.uniform2f(resolution, width, height)
      gl.uniform1f(time, elapsed)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    }

    const tick = (now: number) => {
      if (!running) return
      render(now)
      if (motion.matches) {
        running = false
        return
      }
      frameId = window.requestAnimationFrame(tick)
    }

    const sync = () => {
      const shouldRun = intersecting && !document.hidden
      if (!shouldRun) {
        running = false
        window.cancelAnimationFrame(frameId)
        previousFrame = 0
      } else if (!running) {
        running = true
        frameId = window.requestAnimationFrame(tick)
      }
    }

    const resizeObserver = new ResizeObserver(() => {
      if (motion.matches) render(performance.now())
    })
    resizeObserver.observe(canvas)
    const intersectionObserver = new IntersectionObserver(([entry]) => {
      intersecting = entry.isIntersecting
      sync()
    })
    intersectionObserver.observe(canvas)
    document.addEventListener("visibilitychange", sync)
    motion.addEventListener("change", sync)
    sync()

    return () => {
      running = false
      window.cancelAnimationFrame(frameId)
      resizeObserver.disconnect()
      intersectionObserver.disconnect()
      document.removeEventListener("visibilitychange", sync)
      motion.removeEventListener("change", sync)
      gl.deleteProgram(program)
      gl.deleteVertexArray(vao)
    }
  }, [])

  return <canvas ref={canvasRef} className={`sphere-ai-flow ${className}`} aria-hidden="true" />
}

.sphere-ai-hero {
  position: relative;
  isolation: isolate;
  min-height: 100svh;
  overflow: hidden;
  background: #2e6fae;
  color: #fff;
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

.sphere-ai-hero * { box-sizing: border-box; }
.sphere-ai-hero button, .sphere-ai-hero textarea { font: inherit; }
.sphere-ai-hero button { cursor: pointer; }
.sphere-ai-hero a { color: inherit; text-decoration: none; }

.sphere-ai-flow {
  position: absolute;
  inset: 0;
  z-index: -1;
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.sphere-ai-header {
  position: relative;
  z-index: 5;
  display: flex;
  min-height: 70px;
  align-items: center;
  justify-content: space-between;
  padding: 12px 21px 12px 30px;
}

.sphere-ai-logo {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: -.04em;
}

.sphere-ai-logo svg { flex: none; }

.sphere-ai-nav {
  position: absolute;
  top: 50%;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 27px;
  transform: translate(-50%, -50%);
  white-space: nowrap;
  font-size: 13px;
  font-weight: 400;
}

.sphere-ai-nav > a,
.sphere-ai-nav > button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  padding: 6px 0;
  background: none;
  color: rgba(255,255,255,.95);
  transition: opacity .2s ease;
}

.sphere-ai-nav > a:hover,
.sphere-ai-nav > button:hover { opacity: .72; }

.sphere-ai-nav-popover {
  position: absolute;
  top: 39px;
  right: -18px;
  display: grid;
  min-width: 178px;
  gap: 4px;
  border: 1px solid rgba(255,255,255,.3);
  border-radius: 16px;
  padding: 8px;
  background: rgba(28,64,108,.74);
  box-shadow: 0 14px 36px rgba(10,37,78,.2);
  backdrop-filter: blur(18px);
}

.sphere-ai-nav-popover button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 0;
  border-radius: 10px;
  padding: 9px 10px;
  background: transparent;
  color: #fff;
  text-align: left;
  font-size: 12px;
}

.sphere-ai-nav-popover button:hover { background: rgba(255,255,255,.14); }
.sphere-ai-pricing-popover { right: 64px; width: 235px; white-space: normal; }
.sphere-ai-pricing-popover strong { padding: 7px 10px 0; font-size: 13px; }
.sphere-ai-pricing-popover span { padding: 0 10px; line-height: 1.4; font-size: 11px; opacity: .84; }

.sphere-ai-header-actions { display: flex; align-items: center; gap: 8px; }
.sphere-ai-get-started {
  display: inline-flex;
  height: 45px;
  align-items: center;
  gap: 4px;
  border: 1px solid #69b6d7;
  border-radius: 25px;
  padding: 4px 5px 4px 13px;
