.sphere-ai-modes button {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid rgba(255,255,255,.63);
  border-radius: 24px;
  padding: 6px 15px;
