.sphere-ai-prompt:focus-within { border-color: rgba(255,255,255,.8); }
.sphere-ai-prompt textarea { display: block; width: 100%; min-height: 44px; resize: none; border: 0; padding: 3px 2px; outline: 0; background: none; color: white; font-size: 14px; line-height: 1.5; }
.sphere-ai-prompt textarea::placeholder { color: rgba(255,255,255,.92); opacity: 1; }
.sphere-ai-prompt-toolbar { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.sphere-ai-prompt-tools { display: flex; min-width: 0; align-items: center; gap: 5px; }
.sphere-ai-prompt-tools > button,
