.sphere-ai-send { display: grid; width: 37px; height: 37px; flex: none; place-items: center; border: 1px solid rgba(255,255,255,.58); border-radius: 50%; background: rgba(255,255,255,.025); color: white; transition: background .2s ease, transform .2s ease; }
.sphere-ai-prompt-tools button:hover,
